/** Số di động Việt Nam: 0xxxxxxxxx hoặc +84xxxxxxxxx (đầu số 3, 5, 7, 8, 9). */
export const VN_PHONE_REGEX = /^(0|\+84)(3|5|7|8|9)\d{8}$/;

export const customerSchema = z.object({
  fullName: z
    .string()
    .trim()
    .min(2, "Họ tên phải có ít nhất 2 ký tự")
    .max(50, "Họ tên tối đa 50 ký tự"),
  phone: z.string().trim().regex(VN_PHONE_REGEX, "Số điện thoại không hợp lệ (ví dụ: 0912345678)"),
  email: z
    .string()
    .trim()
    .refine((value) => value === "" || z.email().safeParse(value).success, "Email không hợp lệ")
    .optional(),
  address: z
    .string()
    .trim()
    .min(10, "Địa chỉ phải có ít nhất 10 ký tự")
    .max(200, "Địa chỉ tối đa 200 ký tự"),
  note: z.string().trim().max(200, "Ghi chú tối đa 200 ký tự").optional(),
});

export type CustomerInput = z.infer<typeof customerSchema>;

/** Dữ liệu form thanh toán phía client. */
export const checkoutFormSchema = customerSchema.extend({
  shippingMethod: z.enum(SHIPPING_METHODS, "Vui lòng chọn phương thức giao hàng"),
  paymentMethod: z.enum(PAYMENT_METHODS, "Vui lòng chọn phương thức thanh toán"),
});

export type CheckoutFormValues = z.infer<typeof checkoutFormSchema>;

/** Payload gửi lên POST /api/orders. */
export const placeOrderSchema = z.object({
  customer: customerSchema,
  shippingMethod: z.enum(SHIPPING_METHODS),
  paymentMethod: z.enum(PAYMENT_METHODS),
  items: z
    .array(
      z.object({
        productId: z.string().min(1),
        quantity: z.number().int().min(1).max(MAX_QUANTITY_PER_ITEM),
      }),
    )
    .min(1, "Giỏ hàng đang trống"),
});

export type PlaceOrderInput = z.infer<typeof placeOrderSchema>;

/** { "customer.phone": "Số điện thoại không hợp lệ" } - lấy lỗi đầu tiên của mỗi field. */
export function toFieldErrors(error: z.ZodError): Record<string, string> {
  const fieldErrors: Record<string, string> = {};
  for (const issue of error.issues) {
    const key = issue.path.join(".") || "_form";
    fieldErrors[key] ??= issue.message;
  }
  return fieldErrors;
}
import { NextResponse } from "next/server";
import { orderService } from "@/features/orders/server";
import { handleRouteError, jsonError, readJsonBody } from "@/lib/http";

/** GET /api/orders - danh sách đơn hàng, mới nhất trước. */
export async function GET() {
  try {
    const orders = await orderService.listOrders();
    return NextResponse.json({ orders });
  } catch (error) {
    return handleRouteError(error);
  }
}

/** POST /api/orders - tạo đơn hàng mới. Body: PlaceOrderInput (xem checkout-schema.ts). */
export async function POST(request: Request) {
  const body = await readJsonBody(request);
  if (body === undefined) {
    return jsonError(400, "VALIDATION_ERROR", "Body phải là JSON hợp lệ");
  }

  try {
    const order = await orderService.placeOrder(body);
    return NextResponse.json(order, { status: 201 });
  } catch (error) {
    return handleRouteError(error);
  }
}
import { NextResponse } from "next/server";
import { OrderError } from "@/features/orders/order-errors";

export interface ApiErrorBody {
  error: { code: string; message: string; details?: Record<string, string> };
}

export function jsonError(
  status: number,
  code: string,
  message: string,
  details?: Record<string, string>,
): NextResponse<ApiErrorBody> {
  return NextResponse.json({ error: { code, message, details } }, { status });
}

/** Chuyển lỗi thành response chuẩn { error: { code, message, details? } }. */
export function handleRouteError(error: unknown): NextResponse<ApiErrorBody> {
  if (error instanceof OrderError) {
    return jsonError(error.httpStatus, error.code, error.message, error.details);
  }
  console.error(error);
  return jsonError(500, "INTERNAL_ERROR", "Đã có lỗi xảy ra, vui lòng thử lại sau");
}

/** Đọc JSON body; trả về undefined nếu body không phải JSON hợp lệ. */
export async function readJsonBody(request: Request): Promise<unknown | undefined> {
  try {
    return await request.json();
  } catch {
    return undefined;
  }
}
const currencyFormatter = new Intl.NumberFormat("vi-VN", {
  style: "currency",
  currency: "VND",
  maximumFractionDigits: 0,
});

const dateTimeFormatter = new Intl.DateTimeFormat("vi-VN", {
  dateStyle: "medium",
  timeStyle: "short",
  timeZone: "Asia/Ho_Chi_Minh",
});

/** 1290000 -> "1.290.000 ₫" */
export function formatCurrency(amount: number): string {
  return currencyFormatter.format(amount);
}

export function formatDateTime(isoDate: string): string {
  return dateTimeFormatter.format(new Date(isoDate));
}

/**
 * Chuẩn hóa chuỗi để tìm kiếm không phân biệt hoa thường và dấu tiếng Việt.
 * "Bàn Phím Đẹp" -> "ban phim dep"
 */
export function normalizeText(value: string): string {
  return value
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .replace(/đ/g, "d")
    .replace(/Đ/g, "D")
    .toLowerCase()
    .replace(/\s+/g, " ")
    .trim();
}

