              />
            </Field>
            <Field label="Ghi chú" name="note" error={errors.note} className="sm:col-span-2">
              <textarea
                id="note"
                name="note"
                rows={2}
                value={values.note}
                onChange={handleChange}
                placeholder="Ví dụ: giao giờ hành chính"
                className={cn(
                  inputClass,
                  "h-auto py-2",
